import{z as F,x as l,o as t,c as D,q as r,j as n,D as B,d as A,s,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"运营与合规收束","description":"","frontmatter":{"title":"运营与合规收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-map.md","filePath":"quant/qo-map.md","lastUpdated":1791413859000}'),i={name:"quant/qo-map.md"};function p(C,E,d,m,h,u){const e=l("Mermaid");return t(),D("div",null,[E[2]||(E[2]=r('<h1 id="运营与合规收束" tabindex="-1">运营与合规收束 <a class="header-anchor" href="#运营与合规收束" aria-label="Permalink to &quot;运营与合规收束&quot;">​</a></h1><div class="epigraph"><p>运营回答「今天还能不能开张」，合规回答「开张的方式是否被允许」；两句话都必须每天有数据回答，不能靠感觉。</p><footer>—— 据 RTS 6、SR 11-7 与本课程各课口径整理</footer></div><p><a href="/quant/qo-audit-preparedness">上一课</a>把审计写成可维持的状态；本课程到此收束。八课收成一条主线与一组不变量，并交代与相邻课程的分工。策略怎么想、判据怎么设，是研究课与治理课的对象；本课程回答的始终是两件日常：钱和券每天怎么周转，周转的方式是否始终被允许。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的是：八课合起来，运营与合规到底保证了什么？答案不是「更赚钱」，也不是「永不违规」——运营不创造 alpha，合规不消除风险。它保证的是两组<strong>可回答性</strong>：运营侧，此刻的券还续得上吗（券源台账）、保证金补得上吗（预算与预警带）、今天的清单勾完了吗（日清单）、供应商断一天会怎样（依赖台账）；合规侧，运转在范围内吗（监控）、对监管说清楚了吗（报告）、检查来了拿得出来吗（审计留痕）。所有答案在任何交易日都可查、可复现——这是本课程的全部产出。</p><p><span class="marginnote">「可回答性」可以翻译成：把运营与合规的日常问题变成必须当场交卷的考题——券续得上吗、保证金补得上吗、这个数从哪来——答案只认台账与留痕，不认「我感觉没问题」。它把管理从靠记忆升级成靠数据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主线折成四段。运营单元：<strong>券</strong>是一条有断供风险的供应链，台账三态、到期阶梯、断供预案；<strong>资金</strong>是按日重估的信用额度，预算不等式、两道预警线、追缴与强平预写；<strong>时钟</strong>把前两者装进一天，盘前以清算入账、盘中值守、盘后三本账对账；<strong>底座</strong>是外部依赖，可测、双源、可退出。合规单元是三个出口：红线清单经<strong>监控</strong>在线化，告警分级、阈值重校；记录经<strong>报告</strong>按口径出口，字段、截止、血缘三元组；证据经<strong>审计</strong>准备维持可反查，追加不改写。贯穿的不变量六条：三本账每日对平；截止是硬掩码；关键依赖双源且演练过；告警阈值被定期评估；报告血缘到源；记录只追加不改写。</p>',8)),(t(),n(o,null,{default:B(()=>[s(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEC%5B%22%E5%88%B8%E6%BA%90%E5%8F%B0%E8%B4%A6%EF%BC%9A%E5%8F%AF%E5%80%9F%20%2F%20%E5%9C%A8%E5%80%9F%20%2F%20%E5%B7%B2%E5%8F%AC%E5%9B%9E%22%5D%20--%3E%20DAY%0A%20%20MAR%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E9%A2%84%E7%AE%97%E4%B8%8E%E9%A2%84%E8%AD%A6%E5%B8%A6%22%5D%20--%3E%20DAY%5B%22%E4%BA%A4%E6%98%93%E6%97%A5%E6%B8%85%E5%8D%95%EF%BC%9A%E7%9B%98%E5%89%8D%20%2F%20%E7%9B%98%E4%B8%AD%20%2F%20%E7%9B%98%E5%90%8E%22%5D%0A%20%20DAY%20--%3E%20REC%5B%22%E4%B8%89%E6%9C%AC%E8%B4%A6%E5%AF%B9%E8%B4%A6%EF%BC%9A%E6%9F%9C%E5%8F%B0%20%2F%20%E6%B8%85%E7%AE%97%20%2F%20%E6%89%98%E7%AE%A1%22%5D%0A%20%20VEN%5B%22%E4%BE%9D%E8%B5%96%E5%8F%B0%E8%B4%A6%EF%BC%9ASLA%20%2F%20%E5%8F%8C%E6%BA%90%20%2F%20%E9%80%80%E5%87%BA%22%5D%20-.-%3E%20DAY%0A%20%20REC%20--%3E%20COMP%5B%22%E5%90%88%E8%A7%84%E7%9B%91%E6%8E%A7%EF%BC%9A%E7%8B%AC%E7%AB%8B%E5%BC%95%E6%93%8E%E4%B8%8E%E5%91%8A%E8%AD%A6%22%5D%0A%20%20COMP%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E7%AE%A1%E7%BA%BF%EF%BC%9A%E5%AD%97%E6%AE%B5%20%2F%20%E6%88%AA%E6%AD%A2%20%2F%20%E8%A1%80%E7%BC%98%22%5D%0A%20%20REP%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%E7%95%99%E7%97%95%EF%BC%9A%E5%8F%AA%E8%BF%BD%E5%8A%A0%EF%BC%8C%E5%8F%AF%E5%8F%8D%E6%9F%A5%22%5D%0A%20%20AUD%20-.-%3E%20SEC%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("不变量为什么是这六条：每条堵一个已知失效形态。三本账对平堵口径漂移——同一仓位三个数，是审计与追缴里最常见的第一故障；截止硬掩码堵即兴决策——过点的作业自动阻塞下游，不靠人记得；双源演练堵单点迷信——没切换过的备份等于没有备份；阈值评估堵零告警失灵——监控死掉的形式不是狂响而是安静；血缘到源堵答不上来——问询面前答不出出处的数按不利方向理解；只追加堵历史重写——事后能改的记录证明力为零。六条的机制是同一个：让「运营或合规失效」在发生当天就被看见，而不是在亏损、追缴或问询到来时才暴露。这与"),a("a",{href:"/quant/sl-map"},"生命周期治理收束"),A("的七条不变量互为内外：那边管策略凭什么在跑，这边管跑得是否被允许——两套台账共享「追加不改写」与「单一事实来源」，因为失效形态同源。")],-1)),(t(),n(o,null,{default:B(()=>[s(e,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20F1%5B%22%E5%8F%A3%E5%BE%84%E6%BC%82%E7%A7%BB%EF%BC%9A%E5%90%8C%E4%B8%80%E4%BB%93%E4%BD%8D%E4%B8%89%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20G1%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E4%B8%80%EF%BC%9A%E4%B8%89%E6%9C%AC%E8%B4%A6%E6%AF%8F%E6%97%A5%E5%AF%B9%E5%B9%B3%22%5D%0A%20%20F2%5B%22%E5%8D%B3%E5%85%B4%E5%86%B3%E7%AD%96%EF%BC%9A%E8%BF%87%E6%88%AA%E6%AD%A2%E8%BF%98%E6%83%B3%E5%8A%A8%E6%89%8B%22%5D%20--%3E%20G2%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E4%BA%8C%EF%BC%9A%E6%88%AA%E6%AD%A2%E6%98%AF%E7%A1%AC%E6%8E%A9%E7%A0%81%22%5D%0A%20%20F3%5B%22%E5%8D%95%E7%82%B9%E8%BF%B7%E4%BF%A1%EF%BC%9A%E5%A4%87%E4%BB%BD%E4%BB%8E%E6%9C%AA%E5%88%87%E6%8D%A2%22%5D%20--%3E%20G3%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E4%B8%89%EF%BC%9A%E5%85%B3%E9%94%AE%E4%BE%9D%E8%B5%96%E5%8F%8C%E6%BA%90%E4%B8%94%E6%BC%94%E7%BB%83%22%5D%0A%20%20F4%5B%22%E7%9B%91%E6%8E%A7%E5%AE%89%E9%9D%99%E6%AD%BB%E4%BA%A1%EF%BC%9A%E9%9B%B6%E5%91%8A%E8%AD%A6%22%5D%20--%3E%20G4%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E5%9B%9B%EF%BC%9A%E5%91%8A%E8%AD%A6%E9%98%88%E5%80%BC%E5%AE%9A%E6%9C%9F%E8%AF%84%E4%BC%B0%22%5D%0A%20%20F5%5B%22%E9%97%AE%E8%AF%A2%E9%9D%A2%E5%89%8D%E7%AD%94%E4%B8%8D%E5%87%BA%E5%87%BA%E5%A4%84%22%5D%20--%3E%20G5%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E4%BA%94%EF%BC%9A%E6%8A%A5%E5%91%8A%E8%A1%80%E7%BC%98%E5%88%B0%E6%BA%90%22%5D%0A%20%20F6%5B%22%E4%BA%8B%E5%90%8E%E6%94%B9%E5%86%99%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20G6%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E5%85%AD%EF%BC%9A%E8%AE%B0%E5%BD%95%E5%8F%AA%E8%BF%BD%E5%8A%A0%E4%B8%8D%E6%94%B9%E5%86%99%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">自检三个问题：随机抽一个空头仓位，能否五分钟说出它的券从哪个池子借、哪天到期、断了怎么办？随机抽一条硬截止，能否确认它昨天以硬掩码生效？随机抽一份已报送报告，能否沿血缘走到源系统快照？三个「能」，就是本课程的落地测试。</span></p><p><span class="marginnote">数字实例：三本账对平查的是同一仓位在柜台、清算、托管三处的数是否一致——比如柜台 10,000 股、清算 9,900 股、托管 10,000 股，这 100 股差异若当天不查清，追缴日按最不利口径计保证金，多占的额度没人替你解释；对平就是把差异在当天逼出来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程刻意没覆盖的三块都在知识树的紧邻位置：策略台账、判据与退出是<a href="/quant/sl-map">策略生命周期治理</a>课程的对象，本课程只沿用其台账纪律；数据管线与时点质量是量化数据工程课的对象，报告血缘接在其输出上；风险的计量与限额设计是风险课程的对象，监控引用其限额而不定义它。运营也有成本：每道核对、每个双源都耗人力与预算，按规模与复杂度相称地配——小团队可以窄门，但没有免门。最后一点诚实：运营与合规保证「可周转、可回答、可停」，不保证赚；alpha 仍然是一切的前一课。</p><p><span class="marginnote">常见误区：以为运营与合规做得好就等于少亏钱。它们保证的是「可周转、可回答、可停」——亏损发生时你还能交易、能说清楚、能按预案退出；赚不赚是研究的事。把两者混为一谈，容易把风控做成求签。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>八课两组可回答性：券、资金、时钟、底座答「今天能不能开张」；监控、报告、审计答「开张是否被允许」。</li><li>六条不变量：三本账对平、截止硬掩码、双源演练、阈值评估、血缘到源、记录只追加。</li><li>与治理课程共享台账纪律，失效形态同源：让失效当天现形，不等问询。</li><li>相称性配深度：核对与冗余按规模与复杂度调节，没有免门。</li><li>出处：据 MiFID II 与 RTS 6、SR 11-7（2011）及证券借贷、保证金与报告公开制度口径整理；治理面见<a href="/quant/sl-map">生命周期治理收束</a>，红线清单见<a href="/quant/cn-compliance-map">合规红线与收束</a>。</li></ul>',7))])}const g=F(i,[["render",p]]);export{f as __pageData,g as default};
